1	import { useEffect, useState } from 'react';
2	import { useCushion } from './useCushion.js';
3	import Welcome from './components/Welcome.jsx';
4	import UserDatabase from './components/UserDatabase.jsx';
5	import Dashboard from './components/Dashboard.jsx';
6	
7	const VIEWS = ['users', 'customer', 'stress', 'plan'];
8	const TABS = [['users', '← Accounts'], ['customer', 'Customer'], ['stress', 'Stress Test'], ['plan', 'Plan']];
9	
10	export default function App() {
11	  const c = useCushion();
12	  const [view, setView] = useState('start');
13	  const [accountInput, setAccountInput] = useState(String(c.account));
14	
15	  // The stylesheet switches layouts on body[data-view=...].
16	  useEffect(() => { document.body.dataset.view = view; }, [view]);
17	
18	  function show(next) {
19	    setView(VIEWS.includes(next) ? next : 'users');
20	    window.scrollTo({ top: 0, behavior: 'instant' });
21	  }
22	
23	  function openAccount(id) {
24	    setAccountInput(String(id));
25	    if (!c.busy) c.loadAccount(id);
26	    show('customer');
27	  }
28	
29	  return (
30	    <>
31	      {view === 'start' && <Welcome onDone={() => show('users')} />}
32	      <div id="app-shell" hidden={view === 'start'}>
33	        <header>
34	          <a className="brand" href="/" aria-label="Cushion home" onClick={e => { e.preventDefault(); show('users'); }}>
35	            <img className="brand-pillow" src="/pillow.PNG" alt="" /> Cushion
36	          </a>
37	          <span className="header-note">TANGERINE / RESILIENCE REWIRED</span>
38	          <span id="health" className="badge">{c.health}</span>
39	        </header>
40	        <nav className="cushion-tabs" aria-label="Workspace">
41	          {TABS.map(([v, label]) => (
42	            <button key={v} type="button" aria-current={view === v ? 'page' : undefined} onClick={() => show(v)}>{label}</button>
43	          ))}
44	        </nav>
45	        <UserDatabase hidden={view !== 'users'} ids={c.accountIds} onOpen={openAccount} />
46	        <Dashboard
47	          hidden={view === 'users'}
48	          view={view}
49	          show={show}
50	          c={c}
51	          accountInput={accountInput}
52	          setAccountInput={setAccountInput}
53	        />
54	      </div>
55	    </>
56	  );
57	}
